from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
TESTS = ROOT / "tests" / "v3" / "shukguangyadisk"


def replace_function(text: str, name: str, new_source: str) -> str:
    marker = f"\ndef {name}("
    start = text.find(marker)
    if start < 0:
        raise RuntimeError(f"test function not found: {name}")
    next_start = text.find("\ndef ", start + len(marker))
    if next_start < 0:
        next_start = len(text)
    return text[:start] + "\n" + new_source.rstrip() + "\n" + text[next_start:]


# Empty-folder tests now assert the explicit conflict/execution pipeline instead of the removed installer.
(TESTS / "test_empty_folder_guard_v3410.py").write_text('''from __future__ import annotations\n\nimport json\nfrom pathlib import Path\n\nROOT = Path(__file__).resolve().parents[3]\nPLUGIN = ROOT / "plugins.v3" / "shukguangyadisk"\nGUARD = (PLUGIN / "organizer_empty_folder_guard_v3410.py").read_text(encoding="utf-8")\nCONFLICT = (PLUGIN / "organizer_conflict_resolution_v353.py").read_text(encoding="utf-8")\nEXEC = (PLUGIN / "organizer_execution_v360.py").read_text(encoding="utf-8")\nFILTER = (PLUGIN / "organizer_candidate_filter.py").read_text(encoding="utf-8")\nENTRY = (PLUGIN / "__init__.py").read_text(encoding="utf-8")\nREMOTE = (PLUGIN / "dist" / "assets" / "remoteEntry.js").read_text(encoding="utf-8")\n\n\ndef test_empty_or_missing_folder_skips_moviepilot_recognition():\n    assert "def _live_primary_media_state" in GUARD\n    for token in (\n        "_live_primary_media_state(plugin, item.path)",\n        'live_state in {"empty", "missing"}',\n        "_clear_stale_transient_state(plugin, item)",\n        "_guangya_empty_folder_skip_v3410",\n        "跳过陈旧文件夹任务",\n    ):\n        assert token in CONFLICT, token\n    assert CONFLICT.index("_live_primary_media_state(plugin, item.path)") < CONFLICT.index("_build_moviepilot_kwargs(plugin, item)")\n\n\ndef test_empty_folder_check_uses_moviepilot_media_extensions_only():\n    assert 'get_runtime_setting("RMT_MEDIAEXT")' in GUARD\n    assert "RMT_SUBEXT" not in GUARD\n    assert "RMT_AUDIOEXT" not in GUARD\n\n\ndef test_network_failure_is_not_misclassified_as_empty_folder():\n    for token in ("_api_network_status", "_network_retry_after", 'return "network"'):\n        assert token in GUARD, token\n    assert 'if live_state == "network":' in CONFLICT\n    assert "return False, live_detail" in CONFLICT\n\n\ndef test_empty_skip_does_not_reenter_folder_success_deferred_fallback():\n    assert "_guangya_empty_folder_skip_v3410" in CONFLICT\n    block = EXEC[EXEC.index("if isinstance(item, _FolderBatchEnvelope) and item.directory_mode:"):EXEC.index("return super()._fallback_terminal_state", EXEC.index("if isinstance(item, _FolderBatchEnvelope) and item.directory_mode:"))]\n    assert "_guangya_empty_folder_skip_v3410" in block\n    assert block.index("_guangya_empty_folder_skip_v3410") < block.index("_defer_unconfirmed_members")\n\n\ndef test_v3410_behavior_stays_enabled_without_runtime_installer():\n    assert "install_empty_folder_guard_v3410" not in FILTER\n    assert "install_empty_folder_guard_v3410" not in GUARD\n    assert "from .organizer_empty_folder_guard_v3410 import" in CONFLICT\n    assert "_live_primary_media_state" in CONFLICT\n\n    package = json.loads((ROOT / "package.v3.json").read_text(encoding="utf-8"))["ShukGuangYaDisk"]\n    local = json.loads((PLUGIN / "plugin.json").read_text(encoding="utf-8"))\n    current = package["version"]\n    assert local["version"] == current\n    assert f'plugin_version = "{current}"' in ENTRY\n    assert f"__federation_expose_AssistantPage-v352.js?v={current}" in REMOTE\n    assert package["history"]["v3.4.10"] == "跳过已搬空或无视频的陈旧目录任务，不再触发无意义的 MoviePilot 识别。"\n''', encoding="utf-8")

# Loss-guard tests split helper ownership from final Execution ownership.
(TESTS / "test_loss_guard_v349.py").write_text('''from __future__ import annotations\n\nimport json\nfrom pathlib import Path\n\nROOT = Path(__file__).resolve().parents[3]\nPLUGIN = ROOT / "plugins.v3" / "shukguangyadisk"\nGUARD = (PLUGIN / "organizer_loss_guard_v349.py").read_text(encoding="utf-8")\nCONFLICT = (PLUGIN / "organizer_conflict_resolution_v353.py").read_text(encoding="utf-8")\nEXEC = (PLUGIN / "organizer_execution_v360.py").read_text(encoding="utf-8")\nFILTER = (PLUGIN / "organizer_candidate_filter.py").read_text(encoding="utf-8")\nENTRY = (PLUGIN / "__init__.py").read_text(encoding="utf-8")\nREMOTE = (PLUGIN / "dist" / "assets" / "remoteEntry.js").read_text(encoding="utf-8")\n\n\ndef test_real_folder_transfer_requires_moviepilot_preview_first():\n    for token in (\n        'preview_kwargs["preview"] = True',\n        "preview = transfer_chain.do_transfer(**preview_kwargs)",\n        "_loss_guard._audit_preview(plugin, item, preview)",\n        "_loss_guard._normalize_result(transfer_chain.do_transfer(**kwargs))",\n        "整理前预览",\n        "开始真实整理",\n    ):\n        assert token in CONFLICT, token\n    assert CONFLICT.index('preview_kwargs["preview"] = True') < CONFLICT.index("_loss_guard._normalize_result(transfer_chain.do_transfer(**kwargs))")\n\n\ndef test_preview_guard_blocks_missing_failed_empty_or_duplicate_targets():\n    for token in ("missing = sorted", "failed: List[str]", "empty_target: List[str]", "duplicate_targets", "发现 {len(duplicates)} 组重复目标"):\n        assert token in GUARD, token\n    for token in ("_block_guard_failure", "已阻止真实整理，源文件保持原位", '"folder_safety_blocked"'):\n        assert token in CONFLICT, token\n\n\ndef test_guard_does_not_build_a_second_naming_or_classification_policy():\n    for forbidden in (\n        "RENAME_FORMAT(",\n        "get_rename_path(",\n        "DirectoryHelper().get_dir(",\n        "tmdb_id=",\n        "media_id=",\n        "self._guangya_api.move",\n        "self._guangya_api.copy",\n    ):\n        assert forbidden not in GUARD, forbidden\n    assert "_moviepilot_directory_context" in GUARD\n    assert "_moviepilot_episode_format" in GUARD\n    assert "_moviepilot_tv_context_from_directory_meta" in GUARD\n\n\ndef test_folder_success_cannot_silently_complete_members_without_file_events():\n    assert "def _defer_unconfirmed_members" in GUARD\n    assert "state_store.mark_deferred" in GUARD\n    for token in (\n        "_defer_unconfirmed_members(self, item, reason)",\n        "未收到该成员的 MoviePilot 单文件最终事件",\n        '"folder_partial" if deferred else "folder_completed"',\n        "不标记完成，已退回重试",\n    ):\n        assert token in EXEC, token\n    folder_block = EXEC[EXEC.index("if isinstance(item, _FolderBatchEnvelope) and item.directory_mode:"):EXEC.index("return super()._fallback_terminal_state", EXEC.index("if isinstance(item, _FolderBatchEnvelope) and item.directory_mode:"))]\n    assert "super()._fallback_terminal_state(item, success=True" not in folder_block\n\n\ndef test_loss_guard_is_helper_only_and_execution_is_owner():\n    assert "install_loss_guard_v349" not in FILTER\n    assert "install_loss_guard_v349" not in GUARD\n    assert "GuangYaQueueRecoveryMixin._execute_isolated_transfer" not in GUARD\n    assert "GuangYaQueueRecoveryMixin._fallback_terminal_state" not in GUARD\n    assert "_execute_conflict_aware(self, item)" in EXEC\n    assert "_defer_unconfirmed_members(self, item, reason)" in EXEC\n\n    package = json.loads((ROOT / "package.v3.json").read_text(encoding="utf-8"))["ShukGuangYaDisk"]\n    local = json.loads((PLUGIN / "plugin.json").read_text(encoding="utf-8"))\n    current = package["version"]\n    assert local["version"] == current\n    assert f'plugin_version = "{current}"' in ENTRY\n    assert f"__federation_expose_AssistantPage-v352.js?v={current}" in REMOTE\n    assert package["history"]["v3.4.9"] == "增加整理前目标唯一性校验，防止集数误映射覆盖并进入回收站。"\n''', encoding="utf-8")

